import re
import instructor
from anthropic import Anthropic
from pydantic import BaseModel, model_validator, field_validator

GSTIN = re.compile(r"^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$")

class Invoice(BaseModel):
    gstin: str
    items: list[float]
    total_inr: float

    @field_validator("gstin")
    @classmethod
    def gstin_format(cls, v):
        if not GSTIN.match(v):
            raise ValueError(f"GSTIN {v!r} is not in the 15-character format")
        return v

    @model_validator(mode="after")
    def total_matches(self):
        if abs(sum(self.items) - self.total_inr) > 1:
            raise ValueError(f"total_inr {self.total_inr} != sum of items {sum(self.items)}")
        return self

client = instructor.from_anthropic(Anthropic())

def extract(text: str) -> Invoice:
    return client.messages.create(
        model="claude-sonnet-4-5-20250929", max_tokens=800, max_retries=2,
        response_model=Invoice,             # errors are sent back on each retry
        messages=[{"role": "user", "content": f"<invoice>{text}</invoice>"}])

